package org.securemail.glas.signaling;

import static org.junit.jupiter.api.Assertions.*;
import com.google.gson.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.security.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.attachments.IdentityRemoteAuthority;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;
import org.securemail.glas.protocol600.GlasProtocol600;
import org.securemail.glas.protocol600.GlasProtocol600.*;
import org.securemail.identity.*;

/** Actual Identity HTTP/SQLite/app PoP and separate signalling HTTP. No Tor/audio/native acceptance claim. */
class GlasSignalingIntegration600Test {
  @TempDir Path home;
  IdentityStore identity;IdentityHttpServer identityHttp;IdentityRemoteAuthority remote;GlasRegistry600 registry;GlasSignalingHttp600 http;KeyPair identityKey,serviceKey;Account alice,bob,charlie;MutableClock clock;
  record Account(KeyPair root,KeyPair device,KeyPair recovery,KeyPair app,IdentityStore.Session session,Capability cap){}
  record Reply(int status,JsonObject response){}
  static KeyPair pair()throws Exception{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}
  @BeforeEach void setup()throws Exception{
    identityKey=pair();serviceKey=pair();byte[] audit=new byte[32];new SecureRandom().nextBytes(audit);identity=new IdentityStore(home.resolve("identity/identity.db"),identityKey,audit,Clock.systemUTC());Arrays.fill(audit,(byte)0);
    alice=register();bob=register();charlie=register();identityHttp=new IdentityHttpServer(new InetSocketAddress("127.0.0.1",0),identity,identityKey);identityHttp.start();remote=new IdentityRemoteAuthority(URI.create("http://127.0.0.1:"+identityHttp.port()+"/identity/v1"),identityKey.getPublic().getEncoded());clock=new MutableClock(System.currentTimeMillis());Files.createDirectory(home.resolve("registry"),PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rwx------")));open(10000);
  }
  void open(int capacity)throws Exception{registry=new GlasRegistry600(home.resolve("registry"),remote,identityKey.getPublic().getEncoded(),serviceKey.getPublic().getEncoded(),clock,capacity);http=new GlasSignalingHttp600(new InetSocketAddress("127.0.0.1",0),registry,serviceKey);http.start();}
  @AfterEach void close()throws Exception{if(http!=null)http.close();if(registry!=null)registry.close();if(identityHttp!=null)identityHttp.close();if(identity!=null)identity.close();}
  Account register()throws Exception{KeyPair root=pair(),device=pair(),recovery=pair(),app=pair();long now=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] body=IdentityProtocol.registration(identity.audience(),root.getPublic().getEncoded(),device.getPublic().getEncoded(),recovery.getPublic().getEncoded(),"Контакт",now,nonce);var session=identity.register(root.getPublic().getEncoded(),device.getPublic().getEncoded(),recovery.getPublic().getEncoded(),"Контакт",now,nonce,IdentityProtocol.sign(root.getPrivate(),body),IdentityProtocol.sign(device.getPrivate(),body));return capability(new Account(root,device,recovery,app,session,null),App.GLAS,EnumSet.of(Scope.VOICE_CALL,Scope.CONTACTS_READ));}
  Account capability(Account a,App app,Set<Scope> scopes){long now=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();byte[] body=IdentityProtocol.capabilityRequest(identity.audience(),a.session.accountId(),a.session.deviceId(),a.session.generation(),app,a.app.getPublic().getEncoded(),scopes,600000,now,nonce);Capability cap=identity.issueCapability(a.session.accountId(),a.session.deviceId(),a.session.generation(),app,a.app.getPublic().getEncoded(),scopes,600000,now,nonce,IdentityProtocol.sign(a.device.getPrivate(),body),IdentityProtocol.sign(a.app.getPrivate(),body));return new Account(a.root,a.device,a.recovery,a.app,a.session,cap);}
  Request registration(Account a,Set<String> incoming,Set<String> outgoing)throws Exception{long now=Math.max(clock.millis(),a.cap.issuedAt);Delegation d=new Delegation(identity.audience(),a.root.getPublic().getEncoded(),a.session.deviceId(),a.session.generation(),a.app.getPublic().getEncoded(),now,a.cap.expiresAt,IdentityProtocol.nonce(),new byte[64]);d=d.signed(IdentityProtocol.sign(a.root.getPrivate(),d.signingBytes()));Endpoint e=new Endpoint(IdentityProtocol.id(serviceKey.getPublic().getEncoded()),GlasProtocol600.sha256Delegation(d),GlasProtocol600.onionFromPublicKey(pair().getPublic().getEncoded()),80,now,now+120000,IdentityProtocol.nonce(),new byte[64]);e=e.signed(IdentityProtocol.sign(a.app.getPrivate(),e.signingBytes()));return Request.register(d,e,incoming,outgoing);}
  void both()throws Exception{assertEquals(200,send(alice,registration(alice,Set.of(bob.session.accountId()),Set.of(bob.session.accountId()))).status);assertEquals(200,send(bob,registration(bob,Set.of(alice.session.accountId()),Set.of(alice.session.accountId()))).status);}
  Reply send(Account a,Request request)throws Exception{return send(a,request.encode(),null);}
  Reply send(Account a,byte[] body,IdentityRemoteAuthority.Proof fixed)throws Exception{
    long now=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();var proof=fixed==null?new IdentityRemoteAuthority.Proof(IdentityProtocol.encodeCapability(a.cap),now,nonce,IdentityProtocol.sign(a.app.getPrivate(),IdentityProtocol.requestDigest(a.cap,"glas.call",IdentityProtocol.digest(body),now,nonce))):fixed;
    var c=(HttpURLConnection)new URL("http://127.0.0.1:"+http.port()+"/glas/v1").openConnection(Proxy.NO_PROXY);
    try{c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(3000);c.setReadTimeout(5000);c.setFixedLengthStreamingMode(body.length);c.setRequestProperty("Content-Type","application/octet-stream");c.setRequestProperty("Connection","close");c.setRequestProperty("AEGIS-Capability",proof.capability());c.setRequestProperty("AEGIS-Time",Long.toString(proof.time()));c.setRequestProperty("AEGIS-Nonce",proof.nonce());c.setRequestProperty("AEGIS-Proof",IdentityProtocol.b64(proof.signature()));try(var out=c.getOutputStream()){out.write(body);}int status=c.getResponseCode();byte[] response;try(var in=status<400?c.getInputStream():c.getErrorStream()){response=in.readNBytes(8193);}assertTrue(response.length<8193);assertEquals(response.length,c.getContentLength());assertTrue(IdentityProtocol.verify(serviceKey.getPublic().getEncoded(),IdentityProtocol.response(IdentityProtocol.id(serviceKey.getPublic().getEncoded()),proof.nonce(),body,response),IdentityProtocol.unb64(c.getHeaderField("AEGIS-Signature"),64)));return new Reply(status,IdentityRemoteAuthority.parseStrict(response));}finally{c.disconnect();}
  }
  IdentityRemoteAuthority.Proof proof(Account a,Request request){long now=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();return new IdentityRemoteAuthority.Proof(IdentityProtocol.encodeCapability(a.cap),now,nonce,IdentityProtocol.sign(a.app.getPrivate(),IdentityProtocol.requestDigest(a.cap,"glas.call",IdentityProtocol.digest(request.encode()),now,nonce)));}
  @Test void realHttpRegistrationLookupAndAttestationsRemainBoundToPinnedRootAndApp()throws Exception{both();var reply=send(alice,Request.lookup(bob.root.getPublic().getEncoded()));assertEquals(200,reply.status);var data=reply.response.getAsJsonObject("data");assertEquals(Set.of("delegation","endpoint"),data.keySet());var d=GlasProtocol600.decodeDelegation(IdentityProtocol.unb64(data.get("delegation").getAsString(),1024));var e=GlasProtocol600.decodeEndpoint(IdentityProtocol.unb64(data.get("endpoint").getAsString(),1024));assertTrue(GlasProtocol600.verifyDelegation(d,bob.root.getPublic().getEncoded(),identity.audience(),clock.millis()));assertTrue(e.verify(IdentityProtocol.id(serviceKey.getPublic().getEncoded()),d,clock.millis()));assertFalse(GlasProtocol600.verifyDelegation(d,alice.root.getPublic().getEncoded(),identity.audience(),clock.millis()));}
  @Test void unknownAndNonPermittedContactsGetIdenticalFailureWithoutEndpointOrPolicies()throws Exception{both();var denied=send(alice,Request.lookup(charlie.root.getPublic().getEncoded()));assertEquals(403,denied.status);assertEquals(Set.of("error"),denied.response.getAsJsonObject("data").keySet());var missing=send(alice,Request.lookup(pair().getPublic().getEncoded()));assertEquals(denied.response,missing.response);assertEquals(200,send(bob,registration(bob,Set.of(),Set.of())).status);assertEquals(denied.response,send(alice,Request.lookup(bob.root.getPublic().getEncoded())).response);}
  @Test void bothIncomingAndOutgoingPoliciesAreEnforcedServerSide()throws Exception{assertEquals(200,send(alice,registration(alice,Set.of(bob.session.accountId()),Set.of())).status);assertEquals(200,send(bob,registration(bob,Set.of(alice.session.accountId()),Set.of(alice.session.accountId()))).status);assertEquals(403,send(alice,Request.lookup(bob.root.getPublic().getEncoded())).status);}
  @Test void incomingVerificationSupportsOneWayPolicyWithoutGrantingReverseCalls()throws Exception{assertEquals(200,send(alice,registration(alice,Set.of(),Set.of(bob.session.accountId()))).status);assertEquals(200,send(bob,registration(bob,Set.of(alice.session.accountId()),Set.of())).status);assertEquals(200,send(alice,Request.lookup(bob.root.getPublic().getEncoded(),false)).status);assertEquals(200,send(bob,Request.lookup(alice.root.getPublic().getEncoded(),true)).status);assertEquals(403,send(bob,Request.lookup(alice.root.getPublic().getEncoded(),false)).status);}
  @Test void rootSignatureWrongAppGenerationAndServicePinCannotRegister()throws Exception{var r=registration(alice,Set.of(),Set.of());var badRoot=r.delegation.signed(IdentityProtocol.sign(bob.root.getPrivate(),r.delegation.signingBytes()));assertEquals(403,send(alice,Request.register(badRoot,r.endpoint,Set.of(),Set.of())).status);var badEndpoint=r.endpoint.signed(IdentityProtocol.sign(bob.app.getPrivate(),r.endpoint.signingBytes()));assertEquals(403,send(alice,Request.register(r.delegation,badEndpoint,Set.of(),Set.of())).status);var wrongService=new Endpoint(IdentityProtocol.id(identityKey.getPublic().getEncoded()),r.endpoint.delegationSha256(),r.endpoint.onion,80,r.endpoint.issuedAt,r.endpoint.expiresAt,r.endpoint.nonce,new byte[64]);wrongService=wrongService.signed(IdentityProtocol.sign(alice.app.getPrivate(),wrongService.signingBytes()));assertEquals(403,send(alice,Request.register(r.delegation,wrongService,Set.of(),Set.of())).status);var d=r.delegation;var wrongGeneration=new Delegation(d.audience,d.accountPublic(),d.deviceId,d.generation+1,d.appPublic(),d.issuedAt,d.expiresAt,d.nonce,new byte[64]);wrongGeneration=wrongGeneration.signed(IdentityProtocol.sign(alice.root.getPrivate(),wrongGeneration.signingBytes()));assertFalse(GlasProtocol600.verifyDelegation(wrongGeneration,alice.cap,identityKey.getPublic().getEncoded(),clock.millis()));}
  @Test void mailCapabilityAndReplayCannotBypassGlasScope()throws Exception{Account mail=capability(new Account(alice.root,alice.device,alice.recovery,pair(),alice.session,null),App.MAIL,EnumSet.of(Scope.MAIL_READ));assertEquals(403,send(mail,Request.unregister()).status);var r=registration(alice,Set.of(),Set.of());var p=proof(alice,r);assertEquals(200,send(alice,r.encode(),p).status);assertEquals(403,send(alice,r.encode(),p).status);}
  @Test void modifiedBodyCannotReuseExactSignedOperation()throws Exception{var r=registration(alice,Set.of(),Set.of());var p=proof(alice,r);assertEquals(403,send(alice,Request.unregister().encode(),p).status);assertEquals(200,send(alice,r).status);}
  @Test void targetNewLoginInvalidatesLookupAndCallerNewLoginInvalidatesOldCapability()throws Exception{both();long now=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();identity.login(bob.session.accountId(),bob.session.deviceId(),now,nonce,IdentityProtocol.sign(bob.device.getPrivate(),IdentityProtocol.login(identity.audience(),bob.session.accountId(),bob.session.deviceId(),now,nonce)));assertEquals(403,send(alice,Request.lookup(bob.root.getPublic().getEncoded())).status);assertEquals(403,send(bob,Request.unregister()).status);}
  @Test void endpointExpiryAndUnregisterImmediatelyRemoveVisibility()throws Exception{both();assertEquals(200,send(bob,Request.unregister()).status);assertEquals(200,send(bob,Request.unregister()).status);assertEquals(403,send(alice,Request.lookup(bob.root.getPublic().getEncoded())).status);assertEquals(200,send(bob,registration(bob,Set.of(alice.session.accountId()),Set.of(alice.session.accountId()))).status);clock.value+=120001;assertEquals(403,send(alice,Request.lookup(bob.root.getPublic().getEncoded())).status);}
  @Test void capacityPersistsAcrossRestartAndSymlinksAreRejected()throws Exception{http.close();registry.close();http=null;registry=null;open(1);assertEquals(200,send(alice,registration(alice,Set.of(),Set.of())).status);assertEquals(403,send(bob,registration(bob,Set.of(),Set.of())).status);http.close();registry.close();http=null;registry=null;open(1);assertEquals(403,send(bob,registration(bob,Set.of(),Set.of())).status);Path alias=home.resolve("alias");Files.createSymbolicLink(alias,home.resolve("registry"));assertThrows(IOException.class,()->new GlasRegistry600(alias,remote,identityKey.getPublic().getEncoded(),serviceKey.getPublic().getEncoded(),clock,1));}
  @Test void clockRollbackAndConcurrentRegistryOpeningFailClosed()throws Exception{assertThrows(IOException.class,()->new GlasRegistry600(home.resolve("registry"),remote,identityKey.getPublic().getEncoded(),serviceKey.getPublic().getEncoded(),clock,1));both();http.close();registry.close();http=null;registry=null;clock.value-=60000;assertThrows(IOException.class,()->open(10000));}
  @Test void canonicalProtocolRejectsExtraBytesOversizedContactSetsAndBadOnionChecksum()throws Exception{Request r=registration(alice,Set.of(),Set.of());assertThrows(IOException.class,()->GlasProtocol600.decode(Arrays.copyOf(r.encode(),r.encode().length+1)));Set<String>tooMany=new HashSet<>();for(int i=0;i<257;i++)tooMany.add(String.format("%064x",i));assertThrows(IllegalArgumentException.class,()->Request.register(r.delegation,r.endpoint,tooMany,Set.of()));assertFalse(GlasProtocol600.validOnion("a".repeat(56)+".onion"));assertTrue(GlasProtocol600.validOnion(r.endpoint.onion));assertThrows(IOException.class,()->new GlasSignalingHttp600(new InetSocketAddress("0.0.0.0",0),registry,serviceKey));}
  static final class MutableClock extends Clock{long value;MutableClock(long v){value=v;}public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return Instant.ofEpochMilli(value);}public long millis(){return value;}}
}
